inline size_t BindingSpecCount() { return 493; }

/// Returns the spec for `name`, or nullptr when it is not part of
/// the generated API surface.
inline const BindingSpec* FindBindingSpec(const std::string& name) {
  const BindingSpec* specs = BindingSpecs();
  for (size_t i = 0; i < BindingSpecCount(); ++i) {
    if (name == specs[i].name) return &specs[i];
  }
  return nullptr;
}

/// True when `name` is a binding the IDL marks deprecated. A name that
/// is not part of the surface is not deprecated (it does not exist).
inline bool IsBindingDeprecated(const std::string& name) {
  const BindingSpec* spec = FindBindingSpec(name);
  return spec != nullptr && spec->deprecated != nullptr;
}

/// Canonical binding names grouped by module.
struct ModuleBindings {
  const char* module;
  const char* const* names;
  size_t count;
};

